async def main():
    ipc, store, calls = IPC(), Store(), []
    async def request(url):
        calls.append(url)
        return ['ignored']
    register_handlers(store, ipc, request)
    read, write = (ipc['notion:clipboard:' + name] for name in ('read-rich','write-rich'))
    assert len(ipc) == 2 and await read(None) == []
    blocks = []
    assert await write(None, blocks) == {'ok': True, 'count': 0}
    assert await read(None) is blocks
    assert calls == ['/api/v1/clipboard/blocks'] * 2
    assert await write(None, '😀') == {'ok': True, 'count': 2}
    try:
        await write(None, None)
    except TypeError:
        assert store['lastBlocks'] is None
    else:
        raise AssertionError('expected length access to fail')
    register_handlers(store, ipc)
    try:
        await ipc['notion:clipboard:read-rich'](None)
    except TypeError:
        pass
    else:
        raise AssertionError('expected relative URL to fail')
asyncio.run(main())
